 if schema_extra:schema.update(schema_extra)
 html=f'''<!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | Nitesh Patel</title><meta name="description" content="{escape(desc)}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:url" content="{canonical}"><meta name="twitter:card" content="summary"><meta name="theme-color" content="#081017"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False).replace('<','\\u003c')}</script></head><body><a class="skip" href="#content">Skip to content</a><header><div class="wrap nav"><a class="brand" href="/">NITESH<b>.</b>DEV</a>{nav}</div></header><main id="content">{body}</main><div class="contact-band"><div class="wrap"><span class="eyebrow" style="color:#285332">HAVE A PROJECT IN MIND?</span><h2>Let’s make the next version of your website useful.</h2><a class="button" href="/contact/">Start a conversation</a></div></div><footer><div class="wrap foot"><span>© 2026 Nitesh Patel · Jabalpur, India</span><div><a href="/privacy/">Privacy</a><a href="mailto:niteshpatel7479@gmail.com">Email</a></div></div></footer></body></html>'''
 out=D/path.strip('/')/'index.html' if path!='/' else D/'index.html';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(html);return path
